import numpy as np
from scipy import stats
from sklearn.linear_model import LogisticRegression
from sklearn.feature_selection import mutual_info_classif
from collections import defaultdict

MAX_DRIVERS = 5

def design(feats):
    # Identify potential drivers using Welch's t-test and correlation analysis
    drivers = []
    columns = []
    products = []
    loadings = {}

    # Filter for strong associations (p < 0.01) and high effect sizes
    strong_features = []
    for i, fid in enumerate(feats.ids):
        if feats.types[i] != 'derived':
            t_stat = feats.x[:, i].std() * (feats.x[feats.y==1, i].mean() - feats.x[feats.y==0, i].mean()) / (
                np.sqrt((feats.x[feats.y==1, i].var() + feats.x[feats.y==0, i].var()) / 2))
            p_val = 2 * (1 - stats.t.cdf(abs(t_stat), len(feats.y) - 2))
            if p_val < 0.01 and abs(t_stat) > 3.0:
                strong_features.append((fid, t_stat, p_val))

    # Sort by absolute t-statistic
    strong_features.sort(key=lambda x: abs(x[1]), reverse=True)

    # Select top candidates for drivers
    drivers = [f[0] for f in strong_features[:MAX_DRIVERS]]

    # Add all features with significant associations to columns
    columns = [f[0] for f in strong_features if abs(f[1]) > 2.0]

    # Create products between highly correlated features
    correlations = {}
    for i, fid1 in enumerate(feats.ids):
        for j, fid2 in enumerate(feats.ids):
            if i < j:
                corr = np.corrcoef(feats.x[:, i], feats.x[:, j])[0, 1]
                if abs(corr) >= 0.6:
                    correlations[(fid1, fid2)] = corr

    # Add some product terms involving top features
    for (fid1, fid2), corr in list(correlations.items()):
        if fid1 in columns and fid2 in columns:
            products.append((fid1, fid2))

    # Simple weighted score based on top features
    for i, fid in enumerate(feats.ids):
        if fid in columns:
            loadings[fid] = feats.x[:, i].std()

    return Design(drivers=tuple(drivers), columns=tuple(columns), products=tuple(products), loadings=loadings)

